import numpy as np
from scipy.optimize import least_squares
fams={
 'exp(-kA)t^q': lambda p: p[3]*t**p[4]*np.exp(-p[5]*A),
 'A^p exp(-kA) t^q': lambda p: p[3]*t**p[4]*A**p[6]*np.exp(-p[5]*A),
 'rat t^q/(1+kA)^n': lambda p: p[3]*t**p[4]/(1+p[5]*A)**p[6],
 'A^p/(k+A) t^q': lambda p: p[3]*t**p[4]*A**p[6]/(p[5]+A),
}
for name,f in fams.items():
    best=None; rng=np.random.default_rng(2)
    for i in range(150):
        p0=np.concatenate([rng.normal(size=3)*2,[abs(rng.normal())*2+0.1, rng.normal()*1.5, abs(rng.normal())*2+0.1+0*0, rng.normal()*2, ]])
        p0=np.concatenate([[rng.normal()*10, rng.normal()*2, abs(rng.normal())*2+0.05], rng.normal(size=4)*2+[0,1,0,0][:4]])
        p0=p0[:7] if len(p0)>=7 else np.concatenate([p0,[0.5]*(7-len(p0))])
        def g(p):
            with np.errstate(all='ignore'):
                v=p[0]/t + p[1]*np.log(1+p[2]*t)*A**2 + f(p)
            return np.nan_to_num(v-dA_dt,nan=1e6,posinf=1e6,neginf=-1e6)
        try:
            r=least_squares(g,p0,max_nfev=400)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    print(name, np.round(best.x,4), np.mean(best.fun**2)/dA_dt.var())

